from collections import Counter

def count_components(block_flat, value):
    """Count connected components of 'value' in block_flat using 4-connectivity"""
    n, m = 3, 3
    positions = []
    for idx, v in enumerate(block_flat):
        if v == value:
            r, c = divmod(idx, m)
            positions.append((r, c))

    visited = set()
    components = 0

    for pos in positions:
        if pos in visited:
            continue

        # BFS from this position
        queue = [pos]
        visited.add(pos)
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbor = (nr, nc)
                    if neighbor not in visited:
                        if block_flat[nr * m + nc] == value:
                            visited.add(neighbor)
                            queue.append(neighbor)

        components += 1

    return components, len(positions)

